begin;
update public.tutoring_sessions set data = jsonb_set(data, '{cardIds}', data->'cardIds' || '["53a7def0-8d0d-5d5e-bbaa-b51b899eda0e", "29166b09-ccb7-55e8-94ad-f85160b85dd0", "be1229a1-db80-549b-9e68-2514c8cf03a1", "3da89562-9aa6-5d45-8e01-eff953c8bb20", "4b164c75-711b-5c60-be9a-262e771d81a7", "3840faa9-d638-566a-b69a-1044657bae89", "3b64ff62-b805-506c-b870-e625b93b41ef", "f3c1d4cd-20a3-5c6f-bd77-06d5ae3f925c", "f68cd577-913f-5f7a-9eac-5b5fd65a9f68"]'::jsonb) where id = 'bbf8c3be-f83b-435e-b896-a52a591c7de5' and not (data->'cardIds' ? '53a7def0-8d0d-5d5e-bbaa-b51b899eda0e');
commit;
select jsonb_array_length(data->'cardIds') as flashcards_seance, (select count(*) from public.cards c where c.id in (select jsonb_array_elements_text(s.data->'cardIds'))) as trouvees from public.tutoring_sessions s where id = 'bbf8c3be-f83b-435e-b896-a52a591c7de5';
