insert into public.cards (id, owner_id, data) values
('53a7def0-8d0d-5d5e-bbaa-b51b899eda0e', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "53a7def0-8d0d-5d5e-bbaa-b51b899eda0e", "code": "11ER-074", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "demi-équation", "exemple", "approfondissement"], "front": "**Exemple** : demi-équation du couple $\\mathrm{Cr_2O_7^{2-} / Cr^{3+}}$ (milieu acide) ?", "back": "Cr : $\\mathrm{Cr_2O_7^{2-} = 2\\,Cr^{3+}}$\nO : $+\\,7\\,\\mathrm{H_2O}$ à droite\nH : $+\\,14\\,\\mathrm{H^+}$ à gauche\nCharges : $+12$ à gauche, $+6$ à droite, donc $6\\,e^-$ à gauche.\n$\\mathrm{Cr_2O_7^{2-} + 14\\,H^+ + 6\\,e^- = 2\\,Cr^{3+} + 7\\,H_2O}$", "createdAt": 1793638846494, "updatedAt": 1793638846494, "ocrDone": true}'::jsonb),
('29166b09-ccb7-55e8-94ad-f85160b85dd0', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "29166b09-ccb7-55e8-94ad-f85160b85dd0", "code": "11ER-075", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "demi-équation", "exemple", "approfondissement"], "front": "**Exemple** : demi-équation du couple $\\mathrm{NO_3^- / NO}$ (milieu acide) ?", "back": "O : $\\mathrm{NO_3^- = NO + 2\\,H_2O}$\nH : $\\mathrm{NO_3^- + 4\\,H^+ = NO + 2\\,H_2O}$\nCharges : $+3$ à gauche, $0$ à droite :\n$\\mathrm{NO_3^- + 4\\,H^+ + 3\\,e^- = NO + 2\\,H_2O}$", "createdAt": 1793638846495, "updatedAt": 1793638846495, "ocrDone": true}'::jsonb),
('be1229a1-db80-549b-9e68-2514c8cf03a1', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "be1229a1-db80-549b-9e68-2514c8cf03a1", "code": "11ER-076", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "demi-équation", "exemple", "approfondissement"], "front": "**Exemple** : demi-équation du couple $\\mathrm{CH_3COOH / C_2H_5OH}$ (milieu acide) ?", "back": "$\\mathrm{CH_3COOH + 4\\,H^+ + 4\\,e^- = C_2H_5OH + H_2O}$\nMême méthode qu''avec des ions : C (déjà équilibré), puis O avec $\\mathrm{H_2O}$, H avec $\\mathrm{H^+}$, charges avec $e^-$.", "createdAt": 1793638846496, "updatedAt": 1793638846496, "ocrDone": true}'::jsonb),
('3da89562-9aa6-5d45-8e01-eff953c8bb20', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "3da89562-9aa6-5d45-8e01-eff953c8bb20", "code": "11ER-077", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "équation", "méthode", "approfondissement"], "front": "Après addition des demi-équations, il reste des $\\mathrm{H^+}$ ou des $\\mathrm{H_2O}$ **des deux côtés**. Que faire ?", "back": "On **simplifie** : on retire le même nombre de chaque côté.\nEx. : $28\\,\\mathrm{H^+}$ à gauche et $12\\,\\mathrm{H^+}$ à droite donnent $16\\,\\mathrm{H^+}$ à gauche.\n$\\mathrm{2\\,Cr_2O_7^{2-} + 16\\,H^+ + 3\\,C_2H_5OH \\to 4\\,Cr^{3+} + 3\\,CH_3COOH + 11\\,H_2O}$", "createdAt": 1793638846497, "updatedAt": 1793638846497, "ocrDone": true}'::jsonb),
('4b164c75-711b-5c60-be9a-262e771d81a7', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "4b164c75-711b-5c60-be9a-262e771d81a7", "code": "11ER-078", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "oxydant", "réducteur", "approfondissement"], "front": "$\\mathrm{H_2O_2}$ est-il un **oxydant** ou un **réducteur** ?", "back": "**Les deux** : oxydant du couple $\\mathrm{H_2O_2/H_2O}$, réducteur du couple $\\mathrm{O_2/H_2O_2}$.\nIl peut donc réagir sur lui-même :\n$\\mathrm{2\\,H_2O_2 \\to 2\\,H_2O + O_2}$", "createdAt": 1793638846498, "updatedAt": 1793638846498, "ocrDone": true}'::jsonb),
('3840faa9-d638-566a-b69a-1044657bae89', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "3840faa9-d638-566a-b69a-1044657bae89", "code": "11ER-079", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "proportions stœchiométriques", "méthode", "approfondissement"], "front": "Comment trouver la **masse minimale** (ou le volume minimal) d''un réactif pour consommer entièrement l''autre ?", "back": "On se place dans les **proportions stœchiométriques** : $\\dfrac{n_A}{a} = \\dfrac{n_B}{b}$.\nEx. : $\\mathrm{2\\,Al + 3\\,Cu^{2+}}$ avec $0{,}030$ mol de $\\mathrm{Cu^{2+}}$ : $n(\\mathrm{Al}) = \\dfrac{2 \\times 0{,}030}{3} = 0{,}020$ mol, puis $m = n \\times M$.", "createdAt": 1793638846499, "updatedAt": 1793638846499, "ocrDone": true}'::jsonb),
('3b64ff62-b805-506c-b870-e625b93b41ef', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "3b64ff62-b805-506c-b870-e625b93b41ef", "code": "11ER-080", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "réactif limitant", "approfondissement"], "front": "Un réactif est **en excès**. Qu''en déduit-on ?", "back": "Il ne peut pas être limitant : c''est **l''autre** réactif qui fixe $x_{\\max}$.\nEx. : zinc dans un acide en excès : $n_0(\\mathrm{Zn}) = x_{\\max} = n(\\mathrm{H_2})_{\\text{final}}$.", "createdAt": 1793638846500, "updatedAt": 1793638846500, "ocrDone": true}'::jsonb),
('f3c1d4cd-20a3-5c6f-bd77-06d5ae3f925c', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "f3c1d4cd-20a3-5c6f-bd77-06d5ae3f925c", "code": "11ER-081", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "réactif limitant", "piège", "approfondissement"], "front": "**Piège** : deux réactifs ont la **même quantité** initiale. Sont-ils tous les deux limitants ?", "back": "Pas forcément : on compare $\\dfrac{n}{\\text{coefficient}}$.\nEx. : $\\mathrm{3\\,Cu + 2\\,NO_3^- + 8\\,H^+}$ avec $0{,}040$ mol de $\\mathrm{NO_3^-}$ et de $\\mathrm{H^+}$ : $\\dfrac{0{,}040}{8} \\lt \\dfrac{0{,}040}{2}$, donc $\\mathrm{H^+}$ est limitant.", "createdAt": 1793638846501, "updatedAt": 1793638846501, "ocrDone": true}'::jsonb),
('f68cd577-913f-5f7a-9eac-5b5fd65a9f68', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "f68cd577-913f-5f7a-9eac-5b5fd65a9f68", "code": "11ER-082", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "avancement", "graphique", "approfondissement"], "front": "Graphique $n = f(x)$ des réactifs : comment trouver les **coefficients** et le **réactif limitant** ?", "back": "Chaque droite descend avec une pente égale à **moins le coefficient** du réactif ($n = n_0 - a\\,x$).\nLa droite qui atteint **zéro en premier** est celle du limitant ; l''abscisse de ce point est $x_{\\max}$.", "createdAt": 1793638846502, "updatedAt": 1793638846502, "ocrDone": true}'::jsonb);
